<template><section class="module-page"><header><div><h1>Áo + Ảnh</h1><p>Doanh thu và số lượng theo nhóm sản phẩm</p></div><v-select v-model="period" :items="periods" item-title="label" item-value="value" density="compact" hide-details class="period"/></header><div class="products"><article v-for="p in products" :key="p.key" :class="p.key"><header><v-icon>{{p.icon}}</v-icon><h2>{{p.name}}</h2></header><div class="product-kpis"><div><span>Tổng đơn</span><b>{{p.count}}</b></div><div><span>Doanh thu</span><b>{{money(p.revenue)}}</b></div><div><span>Chưa thu</span><b>{{money(p.outstanding)}}</b></div><div><span>Số lượng</span><b>{{p.quantity}}</b></div></div></article></div><article class="card"><h2>So sánh Áo và Ảnh</h2><table class="report-table"><thead><tr><th>Sản phẩm</th><th>Đơn</th><th>Số lượng</th><th class="money">Doanh thu</th><th class="money">Công nợ</th></tr></thead><tbody><tr v-for="p in products" :key="p.key"><td>{{p.name}}</td><td>{{p.count}}</td><td>{{p.quantity}}</td><td class="money">{{money(p.revenue)}}</td><td class="money">{{money(p.outstanding)}}</td></tr></tbody></table></article></section></template>
<script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{api}from'@/api';const data=ref<any>({}),period=ref('month');const periods=[{value:'month',label:'Tháng này'},{value:'lastMonth',label:'Tháng trước'},{value:'year',label:'Năm nay'}];function range(){const n=new Date();if(period.value==='year')return{from:new Date(n.getFullYear(),0,1).toISOString(),to:new Date(n.getFullYear()+1,0,1).toISOString()};const m=period.value==='lastMonth'?-1:0;return{from:new Date(n.getFullYear(),n.getMonth()+m,1).toISOString(),to:new Date(n.getFullYear(),n.getMonth()+m+1,1).toISOString()}}async function load(){data.value=(await api.get('/delivery/analytics',{params:range()})).data}const products=computed(()=>[{key:'ao',name:'Áo',icon:'mdi-tshirt-crew-outline',...(data.value.byProduct?.ao||{})},{key:'anh',name:'Ảnh',icon:'mdi-camera-outline',...(data.value.byProduct?.anh||{})}]);function money(v:any){return new Intl.NumberFormat('vi-VN').format(Number(v)||0)+' đ'}watch(period,load);onMounted(load)</script><style scoped>@import './delivery-module.css';.products{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}.products>article{background:#fff;border:1px solid #e0e5ec;border-top:4px solid #287be0;border-radius:11px;padding:16px}.products>article.anh{border-top-color:#e5a219}.products header{display:flex;align-items:center;gap:8px}.products h2{font-size:16px}.product-kpis{display:grid;grid-template-columns:1fr 1fr;gap:9px}.product-kpis div{background:#f6f8fb;border-radius:8px;padding:11px}.product-kpis span,.product-kpis b{display:block}.product-kpis span{font-size:11px;color:#667085}.product-kpis b{font-size:17px;margin-top:4px}@media(max-width:700px){.products{grid-template-columns:1fr}}</style>
